import json, random
random.seed(20250807)

calls=[]
def cell(pat,row,ch,note=None,ins=None,vol=None,fx=None,fxp=None):
    a={"pattern":pat,"row":row,"channel":ch}
    if note is not None:a["note"]=n2x(note) if isinstance(note,str) else note
    if ins is not None:a["instrument"]=ins
    if vol is not None:a["volume"]=vol
    if fx is not None:a["effect"]=fx
    if fxp is not None:a["effect_param"]=fxp
    calls.append({"name":"pattern_set_cell","arguments":a})

NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
_M={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
def n2x(s):
    if s in ('===',97): return 97
    return _M[s[:-1].upper()]+(int(s[-1])-1)*12+1
def midi2n(m): return f"{NAMES[m%12]}{m//12}"
def V(x): return 0x10+x

PAD,LEAD,BASS,BUT,ARP,KICK,SNAR,CHAT,OHAT,FXC=range(10)

progress=[
 ("A1",["A2","E3","A3"],57),
 ("E2",["A2","E3","G#3"],56),
 ("F2",["F2","C3","A3"],53),
 ("D2",["F2","C3","D3"],50),
]

M1=[(0,"C5"),(2,"E5"),(4,"C5"),(6,"G4"),(8,"E5"),(12,"D5"),(14,"C5"),
    (16,"A4"),(20,"C5"),(22,"E5"),
    (24,"F5"),(26,"E5"),(28,"D5"),(30,"C5"),
    (32,"E5"),(38,"D5"),(40,"C5"),(42,"D5"),(44,"A4"),
    (48,"G4"),(56,"B4"),(58,"C5"),(60,"D5")]
VARM1=[(24,"B4"),(26,"C5"),(28,"D5"),(30,"E5"),(32,"C5")]
M2=[(0,"E5",58),(28,"G5",50),
    (32,"A5",60),(36,"G5",54),(40,"E5",50),(44,"D5",56),
    (48,"C5",58),(58,"B4",46),(60,"D5",50)]
ARP_SEQ=[12,0,7,12, 0,7,12,0, 7,12,0,7, 12,0,7,12]
RISE_SEQ=[0,4,7,12, 16,19,24,28, 31,24,19,16, 12,7,4,0]

def pad_chord(pat,r,notes,engage=True):
    for i,nn in enumerate(notes):
        if engage: cell(pat,r,PAD,nn,1,None,0xA,((2+i)<<4)|0x01)
        else: cell(pat,r,PAD,'===')

def do_pad(pat,engages):
    on=False; cur=None
    for br in range(4):
        r=br*16
        if engages[br]:
            notes=progress[br][1]
            if not on or cur!=notes: pad_chord(pat,r,notes,True); cur=notes
            on=True
        else:
            if on: pad_chord(pat,r,cur,False)
            on=False

def do_arp(pat,engages,ins=5,seq=ARP_SEQ):
    on=False
    for br in range(4):
        if engages[br]:
            base=progress[br][2]
            for s in range(16):
                m=base+seq[s]
                v=38+(6 if s%4==0 else 0)
                cell(pat,br*16+s,ARP,midi2n(m),ins,V(v),0xC,20+int(40*random.random()))
            on=True
        else:
            if on: cell(pat,br*16,ARP,'===')
            on=False

def do_lead(pat,phrase,replaces=None):
    ph={r:(nn,(it[2] if len(it)>2 else None)) for it in phrase for r,nn in [(it[0],it[1])]}
    if replaces:
        for r,nn in replaces: ph[r]=(nn,None)
    for r in sorted(ph):
        nn,vol=ph[r]
        cell(pat,r,LEAD,nn,2,V(vol) if vol else V(58),0xC,28)
    cell(pat,63,LEAD,'===')

BASS_STEPS=[0,2,4,6,8,10,12,13]
def bass_bar(pat,br,gbar,mode):
    root=progress[gbar%4][0].upper(); r0=br*16
    def put(sub,nn,vol):
        srow=r0+sub//2; dl=sub%2
        if dl: cell(pat,srow,BASS,nn,3,V(vol),0xE,0xD8)
        else:  cell(pat,srow,BASS,nn,3,V(vol))
    if mode=="flat":
        cell(pat,r0,BASS,root,3,V(60)); cell(pat,r0+8,BASS,root,3,V(46)); return
    for sub in BASS_STEPS:
        vol=60 if sub==0 else (54 if sub%4==0 else (50 if sub%2==0 else 44))
        put(sub,root,vol)
    put(15,root,34)
    if mode=="busy":
        put(14,root,48)
        put(15,progress[(gbar+1)%4][0].upper(),40)

def do_drums(pat,brk=False,hats=True,fill=False,kickmode="four"):
    for r in range(64):
        if kickmode=="four" and r%4==0: cell(pat,r,KICK,"C4",6,V(64))
        elif kickmode=="sparse" and r in (0,32): cell(pat,r,KICK,"C4",6,V(64))
        if r in (16,48): cell(pat,r,SNAR,"C4",7,V(56 if kickmode=="sparse" else 58))
        if hats:
            if r%2==1: cell(pat,r,CHAT,"C4",8,V(26 if r%4==3 else 34))
            if r%8==2: cell(pat,r,OHAT,"C4",9,V(30))
        if brk and r in (28,44,60): cell(pat,r,CHAT,"C4",8,V(42))
    if fill:
        cell(pat,62,SNAR,"C4",7,V(46),0xC,24)
        cell(pat,62,OHAT,"C4",9,V(28))

def pluck(pat,events):
    for nn,r,v in events: cell(pat,r,BUT,nn,4,V(v))

# ------- patterns -------
do_pad(0,[1,1,0,0])
do_pad(1,[1,1,0,0]); pluck(1,[("A3",34,32),("E4",40,40),("A4",48,36),("B4",50,28),("C5",52,46)])
do_pad(2,[1,1,0,0])
for gb in range(4): bass_bar(2,gb,gb,"flat")
do_drums(2)
for r,nn in [(0,"E5"),(4,"E5"),(32,"G5"),(36,"G5")]:
    cell(2,r,LEAD,nn,2,V(42),0xC,40)
cell(2,63,LEAD,'===')
